"""Representative local Office inputs, generated by established file libraries."""

from pathlib import Path


def create_office_documents(files: dict[str, Path], image: Path) -> None:
    from docx import Document
    from docx.shared import Inches
    from openpyxl import Workbook
    from pptx import Presentation
    from pptx.dml.color import RGBColor
    from pptx.util import Inches as SlideInches, Pt
    from PIL import Image

    figure = image.parent / "format-document-figure.png"
    with Image.open(image) as bitmap:
        bitmap.resize((600, 400)).save(figure)

    document = Document()
    document.add_heading("文件预览评审 / File viewing review", 0)
    document.add_heading("Reading scope", 1)
    document.add_paragraph("Real Office file preview.")
    document.add_paragraph("中文、English 与分段内容保持可读。")
    document.add_paragraph("Images and tables remain local.", style="List Bullet")
    table = document.add_table(rows=1, cols=3)
    table.style = "Light Shading Accent 1"
    for cell, value in zip(table.rows[0].cells, ("格式", "内容", "结果")):
        cell.text = value
    for values in (("PDF", "Two pages", "Review"), ("Image", "High resolution", "Review")):
        for cell, value in zip(table.add_row().cells, values):
            cell.text = value
    document.add_picture(str(figure), width=Inches(4.5))
    document.add_paragraph("Figure 1 · Local preview image")
    document.add_page_break()
    document.add_heading("Recovery page", 1)
    document.add_paragraph("Second page verification: close and reopen the original file.")
    document.save(files["office"])

    workbook = Workbook()
    sheet = workbook.active
    sheet.title = "Report"
    sheet.merge_cells("A1:E1")
    sheet["A1"] = "Real workbook preview."
    sheet.append(["序号", "文件", "负责人", "大小", "结果"])
    for index in range(1, 109):
        sheet.append([index, f"Preview document {index:03}", "Alice", index * .375, "REVIEW"])
    sheet["Y105"] = "Last workbook viewport."
    sheet.column_dimensions["B"].width = 30
    sheet.column_dimensions["C"].width = 18
    summary = workbook.create_sheet("Summary")
    summary.append(["格式", "数量"])
    summary.append(["Documents", 108])
    workbook.save(files["workbook"])

    slides = Presentation()
    slides.slide_width = SlideInches(12)
    slides.slide_height = SlideInches(6.75)
    for page in (1, 2):
        slide = slides.slides.add_slide(slides.slide_layouts[6])
        fill = slide.background.fill
        fill.solid()
        fill.fore_color.rgb = RGBColor(242, 247, 247)
        title = slide.shapes.add_textbox(SlideInches(.7), SlideInches(.5), SlideInches(11), SlideInches(.9))
        paragraph = title.text_frame.paragraphs[0]
        paragraph.text = f"Real presentation page {page}."
        paragraph.font.size = Pt(28)
        paragraph.font.bold = True
        slide.shapes.add_picture(str(figure), SlideInches(.7), SlideInches(1.6), width=SlideInches(5.8))
        content = slide.shapes.add_textbox(SlideInches(7), SlideInches(1.6), SlideInches(4.2), SlideInches(4))
        for index, line in enumerate(("图文布局 / Images and text", "Preserve local image content", "Close and reopen")):
            paragraph = content.text_frame.paragraphs[0] if index == 0 else content.text_frame.add_paragraph()
            paragraph.text = line
            paragraph.font.size = Pt(20)
    slides.save(files["presentation"])
